def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    barrier = next(
        (r for r, row in enumerate(grid)
         if len(set(row)) == 1 and row[0] != background),
        None
    )
    if barrier is None:
        return [row[:] for row in grid]

    barrier_color = grid[barrier][0]
    cells = [(r, c, grid[r][c])
             for r in range(h) for c in range(w)
             if grid[r][c] not in (background, barrier_color)]
    if not cells:
        return [row[:] for row in grid]

    rows = [r for r, _, _ in cells]
    out = [row[:] for row in grid]
    for r, c, _ in cells:
        out[r][c] = background

    if max(rows) < barrier:
        shift = barrier - 1 - max(rows)
        new_cells = [(r + shift, c, color) for r, c, color in cells]
        marker_row = min(r for r, _, _ in new_cells) - 1
    else:
        shift = barrier + 1 - min(rows)
        new_cells = [(r + shift, c, color) for r, c, color in cells]
        marker_row = max(r for r, _, _ in new_cells) + 1

    for r, c, color in new_cells:
        out[r][c] = color
    if 0 <= marker_row < h:
        out[marker_row] = [8] * w
    return out
